<?php defined('BASEPATH') or exit('No direct script access allowed');$timesheetEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<section id="portal-project-timesheets"><h2>Apontamentos publicados</h2><p>Somente tempos encerrados publicados de tarefas publicadas na revisão atual. O nome do profissional aparece apenas quando autorizado. Estes apontamentos não representam um demonstrativo de faturamento.</p>
<?php if(!$project_timesheets['items']){ ?><p>Nenhum apontamento publicado.</p><?php }else{ ?><div style="overflow-x:auto"><table><thead><tr><th>Profissional</th><th>Tarefa</th><th>Início</th><th>Fim</th><th>Duração</th></tr></thead><tbody><?php foreach($project_timesheets['items'] as $timesheet){$seconds=$timesheet['seconds']; ?><tr><td><?= $timesheetEscape($timesheet['staff_name']??'Identidade não publicada'); ?></td><td><a href="<?= $timesheetEscape($url.'?operation_kind=projects&resource_id='.$timesheets_project_id.'&project_task='.(int)$timesheet['task_id']); ?>"><?= $timesheetEscape($timesheet['task_name']); ?></a></td><td><time><?= $timesheetEscape($timesheet['started_at']); ?></time></td><td><time><?= $timesheetEscape($timesheet['stopped_at']); ?></time></td><td><?= intdiv($seconds,3600); ?>h <?= intdiv($seconds%3600,60); ?>min <?= $seconds%60; ?>s</td></tr><?php } ?></tbody></table></div><?php }if($project_timesheets['next']!==null){ ?><p><a rel="next" href="<?= $timesheetEscape($url.'?operation_kind=projects&resource_id='.$timesheets_project_id.'&timesheets_before='.rawurlencode($project_timesheets['next'])); ?>">Apontamentos anteriores</a></p><?php } ?></section>
